export interface IconProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "color"> {
  size?: number | string;
  /** Accepted for compatibility; v2 icons always use stroke 3. */
  strokeWidth?: number | string;
  fill?: string;
  color?: string;
  absoluteStrokeWidth?: boolean;
}
export type LucideIcon = React.ComponentType<IconProps>;

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ParkIcon = React.ComponentType<any>;

function park(Icon: ParkIcon, name: string): LucideIcon {
  const C = ({ className, size, strokeWidth: _sw, absoluteStrokeWidth: _a, fill, color, ...rest }: IconProps) => {
    void _sw;
    void _a;
    const sized = size != null;
    // Lucide-style sizing (h-4 w-4) sizes the wrapper; the svg fills it.
    const hasBox = /(^|\s)(h-|size-)/.test(className ?? "");
    return (
      <Icon
        theme="outline"
        size={sized ? size : "100%"}
        strokeWidth={3}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill={fill && fill !== "none" ? fill : color ?? "currentColor"}
        aria-hidden={rest["aria-label"] ? undefined : true}
        className={cn("inline-flex shrink-0 items-center justify-center [&>svg]:block", !sized && !hasBox && "h-[1em] w-[1em]", className)}
        {...rest}
      />
    );
  };
  C.displayName = name;
  return C;
}

