// Brand marks IconPark doesn't carry (LinkedIn) or carries in an outdated
// form (the Twitter bird; X uses its own mark now).
function brand(name: string, path: string): LucideIcon {
  const C = ({ className, size, fill, color, strokeWidth: _sw, absoluteStrokeWidth: _a, ...rest }: IconProps) => {
    void _sw;
    void _a;
    const hasBox = /(^|\s)(h-|size-)/.test(className ?? "");
    return (
      <span
        aria-hidden={rest["aria-label"] ? undefined : true}
        className={cn("inline-flex shrink-0 items-center justify-center", size == null && !hasBox && "h-[1em] w-[1em]", className)}
        style={size != null ? { width: size, height: size } : undefined}
        {...rest}
      >
        <svg viewBox="0 0 24 24" width="100%" height="100%" fill={fill && fill !== "none" ? fill : color ?? "currentColor"} aria-hidden>
          <path d={path} />
        </svg>
      </span>
    );
  };
  C.displayName = name;
  return C;
}

